   for(const [Y,W,D] of [[y,w-bevel,d-bevel],[y+bevel,w,d],[y+h-bevel,w,d],[y+h,w-bevel,d-bevel]])for(const [X,Z] of outline(W,D))vertices.push([x+X,Y,z+Z]);
   for(let j=0;j<3;j++)for(let i=0;i<8;i++){const a=v+j*8+i,b=v+j*8+(i+1)%8;face(a,b,b+8,col);face(a,b+8,a+8,col)}
