 function select(id,append=false){if(!append)selection.clear();if(id!==null){const o=objects.find(n=>n.id===id);if(append&&selection.has(id)){for(const n of objects.filter(n=>n.id===id||(o?.group&&n.group===o.group)))selection.delete(n.id)}else if(o){for(const n of objects.filter(n=>n.id===id||(o.group&&n.group===o.group)))selection.add(n.id)}}selected=selection.has(id)?id:([...selection].at(-1)??null);refresh()}
